B=[
('الرِّحْلَةُ الرَّابِعَةُ: الْعَاصِفَةُ','Dördüncü yolculuk: Fırtına',[
('قَالَ السِّنْدِبَادُ: «جَمَعْتُ أَصْحَابِي فِي بَغْدَادَ، وَأَكَلْنَا وَفَرِحْنَا.»','Sindbad dedi ki: “Bağdat’ta arkadaşlarımı topladım; yedik ve sevindik.”'),
('«لَكِنَّ نَفْسِي طَلَبَتِ السَّفَرَ مَرَّةً أُخْرَى، فَخَرَجْتُ إِلَى الْبَصْرَةِ.»','“Ama nefsim yine yolculuk istedi ve Basra’ya çıktım.”'),
('«وَفِي وَسَطِ الْبَحْرِ جَاءَتْ عَاصِفَةٌ قَوِيَّةٌ، فَانْكَسَرَتِ السَّفِينَةُ.»','“Denizin ortasında güçlü bir fırtına geldi ve gemi parçalandı.”'),
('«أَمْسَكْتُ أَنَا وَبَعْضُ التُّجَّارِ لَوْحًا كَبِيرًا، وَبَقِينَا عَلَيْهِ يَوْمًا كَامِلًا.»','“Ben ve bazı tüccarlar büyük bir tahtaya tutunduk ve bir gün boyunca onun üzerinde kaldık.”'),
('«ثُمَّ رَمَتْنَا الْأَمْوَاجُ عَلَى جَزِيرَةٍ فِيهَا نَاسٌ.»','“Sonra dalgalar bizi içinde insanlar bulunan bir adaya attı.”'),
('«فَأَخَذُونَا إِلَى مَلِكِهِمْ، وَأَعْطَوْنَا طَعَامًا غَرِيبًا.»','“Bizi krallarına götürdüler ve bize garip bir yemek verdiler.”'),
('«أَكَلَ أَصْحَابِي مِنْهُ كَثِيرًا، فَذَهَبَ عَقْلُهُمْ، وَصَارُوا يَأْكُلُونَ وَلَا يَشْبَعُونَ.»','“Arkadaşlarım ondan çok yedi; akılları gitti, yiyor ve doymuyorlardı.”'),
('«أَمَّا أَنَا فَلَمْ آكُلْ إِلَّا قَلِيلًا، فَبَقِيَ عَقْلِي مَعِي.»','“Bense pek az yedim; aklım yerinde kaldı.”'),
('«فَهَرَبْتُ فِي اللَّيْلِ، وَمَشَيْتُ سَبْعَةَ أَيَّامٍ.»','“Gece kaçtım ve yedi gün yürüdüm.”')]),
('مَدِينَةُ الْمَلِكِ الطَّيِّبِ','İyi kralın şehri',[
('«وَصَلْتُ إِلَى مَدِينَةٍ كَبِيرَةٍ، فِيهَا أَسْوَاقٌ وَخَيْلٌ كَثِيرَةٌ.»','“Çarşıları ve çok atı olan büyük bir şehre vardım.”'),
('«وَرَأَيْتُ أَنَّ النَّاسَ يَرْكَبُونَ الْخَيْلَ بِلَا سُرُوجٍ.»','“İnsanların atlara eyersiz bindiğini gördüm.”'),
('«فَقُلْتُ لِلْمَلِكِ: يَا مَوْلَايَ، أَنَا أَصْنَعُ لَكَ سَرْجًا جَمِيلًا.»','“Krala dedim ki: Efendim, ben sana güzel bir eyer yaparım.”'),
('«فَصَنَعْتُ سَرْجًا مِنَ الْخَشَبِ وَالْجِلْدِ، وَزَيَّنْتُهُ بِالذَّهَبِ.»','“Tahta ve deriden bir eyer yaptım ve onu altınla süsledim.”'),
('«فَرِحَ الْمَلِكُ بِهِ، وَطَلَبَ الْوُزَرَاءُ وَالْأُمَرَاءُ سُرُوجًا مِثْلَهُ.»','“Kral ona sevindi; vezirler ve emirler de onun gibi eyerler istedi.”'),
('«فَصِرْتُ غَنِيًّا وَمُحْتَرَمًا فِي الْمَدِينَةِ.»','“Şehirde zengin ve saygın biri oldum.”'),
('«وَقَالَ الْمَلِكُ: أُرِيدُ أَنْ تَبْقَى مَعَنَا، فَتَزَوَّجْ مِنْ بَنَاتِ بَلَدِنَا.»','“Kral dedi ki: Bizimle kalmanı istiyorum; memleketimizin kızlarından biriyle evlen.”'),
('«فَتَزَوَّجْتُ امْرَأَةً طَيِّبَةً جَمِيلَةً، وَعِشْتُ مَعَهَا سَعِيدًا.»','“İyi ve güzel bir kadınla evlendim ve onunla mutlu yaşadım.”')]),
('عَادَةٌ غَرِيبَةٌ','Garip bir âdet',[
('«وَفِي يَوْمٍ مَاتَتْ زَوْجَةُ جَارِي، فَذَهَبْتُ أُعَزِّيهِ.»','“Bir gün komşumun eşi öldü; ona başsağlığı dilemeye gittim.”'),
('«فَوَجَدْتُهُ يَبْكِي، وَيُوَدِّعُ أَهْلَهُ.»','“Onu ağlarken ve ailesiyle vedalaşırken buldum.”'),
('«قُلْتُ: لِمَاذَا تُوَدِّعُهُمْ؟»','“Dedim ki: Neden onlarla vedalaşıyorsun?”'),
('«قَالُوا: عَادَتُنَا أَنَّهُ إِذَا مَاتَتِ الزَّوْجَةُ دُفِنَ زَوْجُهَا مَعَهَا حَيًّا.»','“Dediler ki: Âdetimizdir; eş ölürse kocası onunla birlikte diri diri gömülür.”'),
('«فَخِفْتُ خَوْفًا شَدِيدًا، وَقُلْتُ: هَذِهِ عَادَةٌ ظَالِمَةٌ!»','“Çok korktum ve dedim ki: Bu zalim bir âdet!”'),
('«وَدَعَوْتُ اللهَ أَنْ يَحْفَظَ زَوْجَتِي.»','“Ve Allah’ın eşimi korumasını diledim.”'),
('«لَكِنْ بَعْدَ أَشْهُرٍ مَرِضَتْ زَوْجَتِي، وَمَاتَتْ.»','“Ama aylar sonra eşim hastalandı ve öldü.”')]),
('الْبِئْرُ الْمُظْلِمَةُ','Karanlık kuyu',[
('«قُلْتُ لِلْمَلِكِ: أَنَا غَرِيبٌ، وَلَيْسَتْ هَذِهِ عَادَةَ بَلَدِي.»','“Krala dedim ki: Ben yabancıyım, bu benim memleketimin âdeti değil.”'),
('«فَقَالَ: لَا نَسْتَطِيعُ أَنْ نُغَيِّرَ عَادَتَنَا.»','“Dedi ki: Âdetimizi değiştiremeyiz.”'),
('«فَأَنْزَلُونِي فِي بِئْرٍ عَمِيقَةٍ تَحْتَ الْجَبَلِ، وَمَعِي قَلِيلٌ مِنَ الْخُبْزِ وَالْمَاءِ.»','“Beni dağın altındaki derin bir kuyuya indirdiler; yanımda biraz ekmek ve su vardı.”'),
('«ثُمَّ أَغْلَقُوا فَمَ الْبِئْرِ بِحَجَرٍ كَبِيرٍ.»','“Sonra kuyunun ağzını büyük bir taşla kapattılar.”'),
('«كَانَ الْمَكَانُ مُظْلِمًا جِدًّا، وَفِيهِ عِظَامُ مَنْ مَاتُوا قَبْلِي.»','“Yer çok karanlıktı; içinde benden önce ölenlerin kemikleri vardı.”'),
('«أَكَلْتُ قَلِيلًا قَلِيلًا، وَصَبَرْتُ، وَذَكَرْتُ اللهَ كَثِيرًا.»','“Azar azar yedim, sabrettim ve Allah’ı çok andım.”'),
('«وَقُلْتُ: يَا رَبِّ، أَنْتَ أَخْرَجْتَنِي مِنَ الْبَحْرِ وَمِنَ الْوَادِي، فَأَخْرِجْنِي مِنْ هُنَا.»','“Dedim ki: Ya Rabbi, beni denizden ve vadiden çıkardın; beni buradan da çıkar.”')]),
('النُّورُ','Işık',[
('«وَفِي يَوْمٍ سَمِعْتُ صَوْتًا خَفِيفًا فِي آخِرِ الْمَغَارَةِ.»','“Bir gün mağaranın sonunda hafif bir ses duydum.”'),
('«فَمَشَيْتُ نَحْوَهُ، فَرَأَيْتُ حَيَوَانًا صَغِيرًا يَهْرُبُ.»','“Ona doğru yürüdüm ve küçük bir hayvanın kaçtığını gördüm.”'),
('«تَبِعْتُهُ، فَرَأَيْتُ نُورًا ضَعِيفًا مِثْلَ النَّجْمِ.»','“Onun peşinden gittim ve yıldız gibi zayıf bir ışık gördüm.”'),
('«كَانَ ثُقْبًا صَغِيرًا فِي الْجَبَلِ يَخْرُجُ إِلَى الْبَحْرِ.»','“Dağda denize açılan küçük bir delikti.”'),
('«فَحَفَرْتُ بِيَدَيَّ حَتَّى صَارَ الثُّقْبُ وَاسِعًا، وَخَرَجْتُ!»','“Ellerimle kazdım; delik genişleyince dışarı çıktım!”'),
('«رَأَيْتُ السَّمَاءَ وَالْبَحْرَ، فَسَجَدْتُ لِلّٰهِ شُكْرًا.»','“Göğü ve denizi gördüm ve Allah’a şükür secdesi ettim.”')]),
('الْعَوْدَةُ الرَّابِعَةُ','Dördüncü dönüş',[
('«بَقِيتُ عَلَى الشَّاطِئِ أَيَّامًا، آكُلُ مِنَ الثِّمَارِ.»','“Günlerce kıyıda kaldım, meyvelerden yedim.”'),
('«ثُمَّ مَرَّتْ سَفِينَةٌ، فَلَوَّحْتُ لَهُمْ بِثَوْبِي، فَأَخَذُونِي.»','“Sonra bir gemi geçti; elbisemi onlara salladım ve beni aldılar.”'),
('«سَأَلُونِي: كَيْفَ وَصَلْتَ إِلَى هَذَا الْمَكَانِ؟ لَا يَصِلُ إِلَيْهِ أَحَدٌ!»','“Bana sordular: Bu yere nasıl geldin? Buraya kimse ulaşamaz!”'),
('«فَقُلْتُ: كُنْتُ تَاجِرًا، وَانْكَسَرَتْ سَفِينَتِي.»','“Dedim ki: Tüccardım, gemim parçalandı.”'),
('«وَلَمْ أَحْكِ لَهُمْ قِصَّةَ الْبِئْرِ، خَوْفًا أَنْ يَكُونُوا مِنْ أَهْلِ تِلْكَ الْمَدِينَةِ.»','“O şehrin halkından olmalarından korkarak onlara kuyu hikâyesini anlatmadım.”'),
('«ثُمَّ رَجَعْتُ إِلَى بَغْدَادَ، فَأَعْطَيْتُ الصَّدَقَاتِ، وَكَسَوْتُ الْأَيْتَامَ وَالْأَرَامِلَ.»','“Sonra Bağdat’a döndüm; sadakalar verdim, yetimleri ve dulları giydirdim.”'),
('فَقَالَ الْحَمَّالُ: «سُبْحَانَ اللّٰهِ! لَقَدْ رَأَيْتَ الْمَوْتَ بِعَيْنَيْكَ.»','Hamal dedi ki: “Sübhanallah! Ölümü kendi gözlerinle görmüşsün.”'),
('قَالَ السِّنْدِبَادُ: «نَعَمْ، وَغَدًا أَحْكِي لَكَ الرِّحْلَةَ الْخَامِسَةَ.»','Sindbad dedi ki: “Evet; yarın da sana beşinci yolculuğu anlatırım.”')]),
]
